  "Себестоимость действует с начала выбранного дня: поступления этого дня затем меняют среднюю себестоимость. Документы с этой даты пересчитываются автоматически.": "Tannarx tanlangan kun boshidan amal qiladi: shu kungi kirimlar keyin o'rtacha tannarxni o'zgartiradi. Shu sanadan boshlab hujjatlar avtomatik qayta hisoblanadi.",
