  "Прайс-лист по умолчанию для заказа нельзя удалить: сначала назначьте по умолчанию другой прайс-лист или снимите эту отметку": "Buyurtma uchun standart narxlar ro'yxatini o'chirib tashlab bo'lmaydi: avval boshqa narxlar ro'yxatini standart qiling yoki bu belgini olib tashlang",
