  "Базовой валюты ещё нет: первая валюта становится базовой, её курс должен быть 1": "Asosiy valyuta hali yo'q: birinchi valyuta asosiy bo'ladi, uning kursi 1 bo'lishi kerak",
  "Базовой валюты ещё нет: добавьте в файл базовую валюту с курсом 1": "Asosiy valyuta hali yo'q: faylga kursi 1 bo'lgan asosiy valyutani qo'shing",
  "Новая себестоимость действует с того же момента, что и прежняя: документы с этого момента пересчитываются автоматически.": "Yangi tannarx avvalgisi bilan bir xil paytdan boshlab amal qiladi: shu paytdan boshlab hujjatlar avtomatik qayta hisoblanadi.",
